<?php
require_once __DIR__.'/../core/Controller.php'; require_once __DIR__.'/../models/Staff.php'; require_once __DIR__.'/../models/BranchStock.php'; require_once __DIR__.'/../models/BranchPosStock.php';
class BranchInventoryController extends Controller { private Staff $staff;private BranchStock $inventory;private BranchPosStock $pos;public function __construct(){if(session_status()===PHP_SESSION_NONE)session_start();$this->staff=new Staff();$this->inventory=new BranchStock();$this->pos=new BranchPosStock();}private function profile():array{$p=$this->requireActiveStaff();if(!in_array($p['position'],['branch_manager','inventory_staff'],true)){http_response_code(403);exit('Access denied.');}return $p;}public function index():void{$p=$this->profile();$this->view('manager/inventory',['profile'=>$p,'rows'=>$this->inventory->forBranch((int)$p['branch_id']),'active'=>'inventory','error'=>$_GET['error']??null,'success'=>$_GET['success']??null]);}public function transfer():void{$p=$this->profile();if($p['position']!=='branch_manager'){http_response_code(403);exit('Only the Branch Manager can move stock to Branch POS or return it to the Seller.');}$direction=$_POST['direction']??'';$r=$this->pos->transfer((int)$p['branch_id'],(int)($_POST['product_id']??0),trim($_POST['variant_size']??''),trim($_POST['variant_color']??''),(int)($_POST['quantity']??0),$direction,(int)$_SESSION['user_id'],true,trim($_POST['note']??''));$this->redirect($r['success']?'/manager/inventory?success='.urlencode('Stock moved.'):'/manager/inventory?error='.urlencode($r['error']));}}
